/*
 * To Top 轻量 LaTeX 子集渲染器（离线兜底实现）。
 *
 * 背景：KaTeX 的 katex.min.js / katex.min.css / fonts 需要从上游发行包下载后放入
 * assets/katex/。构建环境无外网时无法下载，因此这里提供一个**自研**的极简渲染器，
 * 覆盖中学数学题干与解题步骤里最常见的语法，保证公式区块不空白。
 *
 * 与 KaTeX 的关系：
 * - 一旦 assets/katex/katex.min.js 就位，宿主页会优先使用 KaTeX，本文件自动不被调用；
 * - 本文件不是 KaTeX、不是 MathJax，也不加载任何网络资源，只输出纯 HTML/CSS。
 *
 * 支持：分组 {} / 分式 \frac \dfrac \tfrac / 根号 \sqrt 与 \sqrt[n]{} /
 *      上下标 _ ^ / \text \mathrm \mathbf / \left( ... \right) /
 *      希腊字母与常用符号命令 / 函数名 \sin \cos \log \ln \lim \sum \int /
 *      空白命令 \, \; \! \quad \qquad \  与 \begin{cases}...\end{cases} 的简化处理。
 * 不支持：矩阵、多行对齐环境、\overbrace 等装饰。遇到未知命令时按原文输出。
 */
(function () {
    "use strict";

    var GREEK = {
        alpha: "\u03B1", beta: "\u03B2", gamma: "\u03B3", delta: "\u03B4", epsilon: "\u03F5",
        varepsilon: "\u03B5", zeta: "\u03B6", eta: "\u03B7", theta: "\u03B8", vartheta: "\u03D1",
        iota: "\u03B9", kappa: "\u03BA", lambda: "\u03BB", mu: "\u03BC", nu: "\u03BD", xi: "\u03BE",
        pi: "\u03C0", rho: "\u03C1", sigma: "\u03C3", tau: "\u03C4", upsilon: "\u03C5", phi: "\u03D5",
        varphi: "\u03C6", chi: "\u03C7", psi: "\u03C8", omega: "\u03C9",
        Gamma: "\u0393", Delta: "\u0394", Theta: "\u0398", Lambda: "\u039B", Xi: "\u039E",
        Pi: "\u03A0", Sigma: "\u03A3", Phi: "\u03A6", Psi: "\u03A8", Omega: "\u03A9"
    };

    var SYMBOLS = {
        times: "\u00D7", cdot: "\u00B7", div: "\u00F7", pm: "\u00B1", mp: "\u2213",
        leq: "\u2264", le: "\u2264", geq: "\u2265", ge: "\u2265", neq: "\u2260", ne: "\u2260",
        approx: "\u2248", equiv: "\u2261", sim: "\u223C", cong: "\u2245", propto: "\u221D",
        infty: "\u221E", partial: "\u2202", nabla: "\u2207", angle: "\u2220", perp: "\u22A5",
        parallel: "\u2225", triangle: "\u25B3", square: "\u25A1", circ: "\u25CB",
        because: "\u2235", therefore: "\u2234", forall: "\u2200", exists: "\u2203",
        in: "\u2208", notin: "\u2209", subset: "\u2282", subseteq: "\u2286", cup: "\u222A",
        cap: "\u2229", emptyset: "\u2205", varnothing: "\u2205", cdots: "\u22EF", ldots: "\u2026",
        dots: "\u2026", to: "\u2192", rightarrow: "\u2192", leftarrow: "\u2190",
        Rightarrow: "\u21D2", Leftarrow: "\u21D0", leftrightarrow: "\u2194",
        uparrow: "\u2191", downarrow: "\u2193", sum: "\u2211", prod: "\u220F",
        int: "\u222B", oint: "\u222E", lim: "lim", prime: "\u2032",
        degree: "\u00B0", percent: "%", "%": "%", "{": "{", "}": "}", "$": "$",
        "&": "&", "#": "#", "_": "_", "|": "\u2225"
    };

    var FUNCTIONS = {
        sin: "sin", cos: "cos", tan: "tan", cot: "cot", sec: "sec", csc: "csc",
        arcsin: "arcsin", arccos: "arccos", arctan: "arctan",
        log: "log", ln: "ln", lg: "lg", exp: "exp", lim: "lim", max: "max", min: "min",
        sup: "sup", inf: "inf", det: "det", dim: "dim", deg: "deg"
    };

    var SPACES = { ",": "0.17em", ";": "0.28em", ":": "0.22em", "!": "-0.17em", " ": "0.25em", quad: "1em", qquad: "2em" };

    function makeEl(className, text) {
        var el = document.createElement("span");
        if (className) {
            el.className = className;
        }
        if (text !== undefined && text !== null) {
            el.textContent = text;
        }
        return el;
    }

    /** 词法分析：把 LaTeX 源码切成 token 序列。 */
    function tokenize(source) {
        var tokens = [];
        var index = 0;
        while (index < source.length) {
            var ch = source.charAt(index);
            if (ch === "\\") {
                var next = source.charAt(index + 1);
                if (next === "") {
                    tokens.push({ type: "char", value: "\\" });
                    index += 1;
                    continue;
                }
                if (!/[a-zA-Z]/.test(next)) {
                    tokens.push({ type: "command", value: next, single: true });
                    index += 2;
                    continue;
                }
                var name = "";
                index += 1;
                while (index < source.length && /[a-zA-Z]/.test(source.charAt(index))) {
                    name += source.charAt(index);
                    index += 1;
                }
                tokens.push({ type: "command", value: name, single: false });
                continue;
            }
            if (ch === "{" || ch === "}" || ch === "_" || ch === "^") {
                tokens.push({ type: ch });
                index += 1;
                continue;
            }
            tokens.push({ type: "char", value: ch });
            index += 1;
        }
        return tokens;
    }

    /** 解析器：把 token 序列解析成轻量 AST。 */
    function parse(tokens) {
        var position = 0;

        function peek() {
            return tokens[position];
        }

        function take() {
            var token = tokens[position];
            position += 1;
            return token;
        }

        function parseGroup() {
            if (peek() && peek().type === "{") {
                take();
                var nodes = parseNodes(false);
                if (peek() && peek().type === "}") {
                    take();
                }
                return { type: "group", children: nodes };
            }
            var single = take();
            return single ? parseAtom(single) : { type: "text", value: "" };
        }

        function parseArg() {
            return parseGroup();
        }

        function parseScripts(base) {
            var node = base;
            for (;;) {
                var token = peek();
                if (!token || (token.type !== "_" && token.type !== "^")) {
                    return node;
                }
                take();
                var script = parseArg();
                if (token.type === "^") {
                    node = { type: "sup", base: node, script: script };
                } else {
                    node = { type: "sub", base: node, script: script };
                }
            }
        }

        function parseAtom(token) {
            if (!token) {
                return { type: "text", value: "" };
            }
            if (token.type === "char") {
                if (token.value === "-") {
                    return { type: "text", value: "\u2212" };
                }
                return { type: "text", value: token.value };
            }
            if (token.type === "command") {
                return parseCommand(token);
            }
            return { type: "text", value: "" };
        }

        function parseCommand(token) {
            var name = token.value;
            if (token.single) {
                if (SPACES[name] !== undefined) {
                    return { type: "space", width: SPACES[name] };
                }
                if (SYMBOLS[name] !== undefined) {
                    return { type: "text", value: SYMBOLS[name] };
                }
                if (name === "\\") {
                    return { type: "space", width: "1em" };
                }
                return { type: "text", value: name };
            }
            if (GREEK[name] !== undefined) {
                return { type: "text", value: GREEK[name], italic: true };
            }
            if (FUNCTIONS[name] !== undefined) {
                return { type: "text", value: FUNCTIONS[name], upright: true };
            }
            if (SYMBOLS[name] !== undefined) {
                return { type: "text", value: SYMBOLS[name] };
            }
            if (name === "frac" || name === "dfrac" || name === "tfrac") {
                var numerator = parseArg();
                var denominator = parseArg();
                return { type: "frac", numerator: numerator, denominator: denominator };
            }
            if (name === "sqrt") {
                var degree = null;
                if (peek() && peek().type === "char" && peek().value === "[") {
                    take();
                    var degreeTokens = [];
                    while (peek() && !(peek().type === "char" && peek().value === "]")) {
                        degreeTokens.push(take());
                    }
                    if (peek()) {
                        take();
                    }
                    degree = parseFromTokens(degreeTokens);
                }
                var radicand = parseArg();
                return { type: "sqrt", degree: degree, radicand: radicand };
            }
            if (name === "text" || name === "mathrm" || name === "textrm" || name === "operatorname") {
                var content = readRawGroup();
                return { type: "text", value: content, upright: true };
            }
            if (name === "mathbf" || name === "textbf") {
                return { type: "bold", child: { type: "text", value: readRawGroup(), upright: true } };
            }
            if (name === "left" || name === "right") {
                var delimiter = peek();
                if (delimiter) {
                    take();
                    if (delimiter.type === "char") {
                        return { type: "text", value: delimiter.value, bracket: true };
                    }
                    if (delimiter.type === "command") {
                        if (delimiter.value === ".") {
                            return { type: "text", value: "" };
                        }
                        if (SYMBOLS[delimiter.value] !== undefined) {
                            return { type: "text", value: SYMBOLS[delimiter.value] };
                        }
                        return { type: "text", value: delimiter.value };
                    }
                }
                return { type: "text", value: "" };
            }
            if (name === "overline" || name === "bar") {
                return { type: "overline", child: parseArg() };
            }
            if (name === "vec") {
                return { type: "accent", mark: "\u2192", child: parseArg() };
            }
            if (name === "begin" || name === "end") {
                readRawGroup();
                return { type: "text", value: "" };
            }
            return { type: "text", value: name };
        }

        function readRawGroup() {
            if (!peek() || peek().type !== "{") {
                return "";
            }
            take();
            var depth = 1;
            var out = "";
            while (peek()) {
                var token = take();
                if (token.type === "{") {
                    depth += 1;
                    out += "{";
                } else if (token.type === "}") {
                    depth -= 1;
                    if (depth === 0) {
                        break;
                    }
                    out += "}";
                } else if (token.type === "char") {
                    out += token.value;
                } else if (token.type === "command") {
                    out += token.single ? token.value : token.value;
                }
            }
            return out;
        }

        function parseNodes(stopAtBrace) {
            var nodes = [];
            while (peek()) {
                if (stopAtBrace && peek().type === "}") {
                    return nodes;
                }
                var token = take();
                var atom = parseAtom(token);
                nodes.push(parseScripts(atom));
            }
            return nodes;
        }

        function parseFromTokens(list) {
            var savedTokens = tokens;
            var savedPosition = position;
            tokens = list.concat([{ type: "eof" }]);
            position = 0;
            var result = parseNodes(false);
            tokens = savedTokens;
            position = savedPosition;
            return { type: "group", children: result };
        }

        return parseNodes(false);
    }

    /** 渲染器：把 AST 转成 DOM。 */
    function render(nodes, parent) {
        for (var i = 0; i < nodes.length; i += 1) {
            renderNode(nodes[i], parent);
        }
    }

    function renderNode(node, parent) {
        if (!node) {
            return;
        }
        switch (node.type) {
            case "text": {
                var span = makeEl("tt-t", node.value);
                if (node.italic) {
                    span.style.fontStyle = "italic";
                }
                if (node.upright) {
                    span.style.fontStyle = "normal";
                }
                parent.appendChild(span);
                break;
            }
            case "space": {
                var space = makeEl("tt-space", "");
                space.style.display = "inline-block";
                space.style.width = node.width;
                parent.appendChild(space);
                break;
            }
            case "group": {
                render(node.children, parent);
                break;
            }
            case "frac": {
                var frac = makeEl("tt-frac");
                frac.style.display = "inline-flex";
                frac.style.flexDirection = "column";
                frac.style.verticalAlign = "middle";
                frac.style.textAlign = "center";
                frac.style.margin = "0 0.15em";
                var top = makeEl("tt-num");
                top.style.display = "block";
                top.style.padding = "0 0.2em";
                render([node.numerator], top);
                var bar = makeEl("tt-bar");
                bar.style.display = "block";
                bar.style.borderTop = "1px solid currentColor";
                bar.style.margin = "0.08em 0";
                var bottom = makeEl("tt-den");
                bottom.style.display = "block";
                bottom.style.padding = "0 0.2em";
                render([node.denominator], bottom);
                frac.appendChild(top);
                frac.appendChild(bar);
                frac.appendChild(bottom);
                parent.appendChild(frac);
                break;
            }
            case "sqrt": {
                var sqrt = makeEl("tt-sqrt");
                sqrt.style.whiteSpace = "nowrap";
                var rootSign = makeEl("tt-root", "\u221A");
                sqrt.appendChild(rootSign);
                if (node.degree) {
                    var degree = makeEl("tt-degree");
                    degree.style.fontSize = "0.62em";
                    degree.style.verticalAlign = "super";
                    render([node.degree], degree);
                    sqrt.appendChild(degree);
                }
                var body = makeEl("tt-radicand");
                body.style.borderTop = "1px solid currentColor";
                body.style.padding = "0.08em 0.12em 0 0.12em";
                render([node.radicand], body);
                sqrt.appendChild(body);
                parent.appendChild(sqrt);
                break;
            }
            case "sup": {
                var supBase = makeEl("tt-supbase");
                render([node.base], supBase);
                var sup = document.createElement("sup");
                sup.style.fontSize = "0.72em";
                render([node.script], sup);
                supBase.appendChild(sup);
                parent.appendChild(supBase);
                break;
            }
            case "sub": {
                var subBase = makeEl("tt-subbase");
                render([node.base], subBase);
                var sub = document.createElement("sub");
                sub.style.fontSize = "0.72em";
                render([node.script], sub);
                subBase.appendChild(sub);
                parent.appendChild(subBase);
                break;
            }
            case "bold": {
                var bold = makeEl("tt-bold");
                bold.style.fontWeight = "700";
                render([node.child], bold);
                parent.appendChild(bold);
                break;
            }
            case "overline": {
                var over = makeEl("tt-overline");
                over.style.borderTop = "1px solid currentColor";
                over.style.paddingTop = "0.08em";
                render([node.child], over);
                parent.appendChild(over);
                break;
            }
            case "accent": {
                var accent = makeEl("tt-accent");
                var mark = makeEl("tt-accent-mark", node.mark);
                mark.style.display = "block";
                mark.style.textAlign = "center";
                mark.style.fontSize = "0.8em";
                var accentBody = makeEl("tt-accent-body");
                accentBody.style.display = "block";
                render([node.child], accentBody);
                accent.appendChild(mark);
                accent.appendChild(accentBody);
                parent.appendChild(accent);
                break;
            }
            default: {
                render([node.child], parent);
                break;
            }
        }
    }

    /**
     * 渲染入口：把 latex 渲染到 container 里。
     * @returns {boolean} 是否成功（渲染器对未知语法宽容，几乎总是返回 true）
     */
    function renderLatex(latex, container) {
        var nodes = parse(tokenize(String(latex || "")));
        render(nodes, container);
        return true;
    }

    window.ToTopLatexFallback = { render: renderLatex, parse: parse, tokenize: tokenize };
})();
